# ==========================================================================
# f9-r3b-chunk-00  --  Kaggle CERTIFY kernel, q=9 R3b closed-box winding
# N_PRIMARY=32 (N_COMPARISON=28 cross-check also run). chunk-00 IS the
# whole box (4 edges, 16 arcs) -- fits one session.
# Self-contained: recreates the exact absolute-path scaffold
# f9f12_certify_r3b_flagship.py expects, then runs it unmodified.
# ==========================================================================
import base64, os, subprocess, sys, json, time, zlib

try:
    import flint  # noqa
except Exception:
    subprocess.run([sys.executable, "-m", "pip", "install", "-q", "python-flint"], check=True)

FILES_B64 = {
    "Users/za/Documents/farey-hecke/.worktrees/aletheia-restore/code/zeta_cert_rosen_even.py": "",
    "Users/za/Documents/farey-hecke/.worktrees/aletheia-restore/code/zeta_cert_rosen.py": "",
    "Users/za/Documents/farey-hecke/.worktrees/aletheia-restore/code/zeta_cert_rosen_q5.py": "",
    "Users/za/Documents/farey-hecke/research_notes/rh_goals_2026-08-14/lane_f/f9f12_certify_r3b_flagship.py": "",
}

for rel_path, b64 in FILES_B64.items():
    dest = os.path.join("/", rel_path)
    os.makedirs(os.path.dirname(dest), exist_ok=True)
    with open(dest, "wb") as f:
        f.write(zlib.decompress(base64.b64decode(b64)))

LANE_F = "/Users/za/Documents/farey-hecke/research_notes/rh_goals_2026-08-14/lane_f"
OUT = "/kaggle/working"
os.makedirs(OUT, exist_ok=True)

for N in (32, 28):
    cmd = [
        sys.executable, os.path.join(LANE_F, "f9f12_certify_r3b_flagship.py"),
        "--q", "9", "--N", str(N),
        "--receipt", os.path.join(OUT, f"F9_R3B_CHUNK_00_N{N}_RECEIPT.json"),
        "--report", os.path.join(OUT, f"F9_R3B_CHUNK_00_N{N}_CERT.md"),
    ]
    print("RUNNING:", " ".join(cmd), flush=True)
    t0 = time.time()
    result = subprocess.run(cmd, cwd=LANE_F)
    print("EXIT CODE:", result.returncode, "  wall_seconds:", time.time() - t0, flush=True)
    if result.returncode != 0:
        sys.exit(result.returncode)
sys.exit(0)
